/*
  REMAINING 20% REVENUE PRODUCTS (PARETO LONG TAIL)
  ==============================================================================
  Identifies individual product SKUs that fall into the bottom 20% of 
  revenue contribution (the long tail).
  
  Outputs:
  - Product identifiers (stock_code, description)
  - Rounded total revenue per product
  - Exact individual percentage contribution (pct_share)
  ==============================================================================
*/

WITH product_revenue AS
(
    -- Calculates total revenue generated by each unique product SKU
    SELECT
        stock_code,
        description,
        SUM(revenue) AS total_revenue
    FROM 'valid_product_sales.csv'
    GROUP BY
        stock_code,
        description
),

with_global_total AS
(
    -- Appends overall global revenue across all products to every row using a window sum
    SELECT
        stock_code,
        description,
        total_revenue,
        SUM(total_revenue) OVER () AS global_revenue
    FROM product_revenue
),

with_pct_share AS
(
    -- Calculates each product's percentage contribution to total global sales
    -- Uses NULLIF to prevent potential division-by-zero errors
    SELECT
        stock_code,
        description,
        total_revenue,
        (total_revenue / NULLIF(global_revenue, 0)) * 100.0 AS pct_share
    FROM with_global_total
),

with_cumulative_pct_share AS
(
    -- Ranks products by revenue contribution and computes an exact running total percent
    -- Uses `stock_code ASC` as a tie-breaker and explicit `ROWS` frame specification 
    -- to prevent duplicate row aggregation and ensure deterministic row-by-row accumulation
    SELECT
        stock_code,
        description,
        total_revenue,
        pct_share,
        SUM(pct_share) OVER (
            ORDER BY pct_share DESC, stock_code ASC
            ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
        ) AS cumulative_pct_share
    FROM with_pct_share
),

flagged AS
(
    -- Identifies products in the top 80% revenue group vs. the bottom 20%
    -- Assigns flag = 1 to top drivers (including the cutoff SKU that crosses 80%)
    -- Assigns flag = 0 to long-tail products contributing strictly beyond the 80% mark
    SELECT
        *,
        CASE
            WHEN cumulative_pct_share <= 80
                OR COALESCE(LAG(cumulative_pct_share) OVER (ORDER BY pct_share DESC, stock_code ASC), 0) < 80
                THEN 1
            ELSE 0
        END AS product_inclusion_flag
    FROM with_cumulative_pct_share
)

-- Filters for remaining products (flag = 0) and outputs clean product-level metrics
SELECT
    stock_code,
    description,
    ROUND(total_revenue, 2) AS total_revenue,
    ROUND(pct_share, 2) AS pct_share
FROM flagged
WHERE product_inclusion_flag = 0
ORDER BY
    pct_share DESC,
    stock_code ASC;